PI = 3.141592653589793
wp = get_waypoint()
gl = get_goal()
passed_waypoint = False

for _ in range(60):
    pose = get_pose()
    x, y, h = pose['x'], pose['y'], pose['heading_deg']
    d_way = distance_to(wp['x'], wp['y'])
    d_goal = distance_to(gl['x'], gl['y'])

    if not passed_waypoint:
        if d_way > 0.6:
            th = heading_to(wp['x'], wp['y'])
            err = th - h
            if err > 180:
                err -= 360
            elif err < -180:
                err += 360
            wz = err * PI / 180.0
            if wz > 1.0:
                wz = 1.0
            if wz < -1.0:
                wz = -1.0
            vx, vy = 0.5, 0.0
        else:
            passed_waypoint = True
            log("Passed waypoint, heading to goal")
    else:
        if d_goal > 0.5:
            th = heading_to(gl['x'], gl['y'])
            err = th - h
            if err > 180:
                err -= 360
            elif err < -180:
                err += 360
            wz = err * PI / 180.0
            if wz > 1.0:
                wz = 1.0
            if wz < -1.0:
                wz = -1.0
            vx, vy = 0.5, 0.0
        else:
            stop(1)
            log("Goal reached, stopped")
            break

    r = walk(vx, vy, wz, 1)
    if r.get('fell'):
        log("Robot fell")
        break
